    <tr><th>Artículo</th><th>Costo</th><th>Reembolsos/Créditos</th><th>Costo neto</th></tr>
  </thead>
  <tbody>
    <tr><td>Renovación de cocina</td><td>$55,000</td><td>—</td><td>$55,000</td></tr>
    <tr><td>Conversión de ducha a ras de suelo (hogar de personas mayores)</td><td>$18,000</td><td>HRTC: $2,700 (15% de $18K)</td><td>$15,300</td></tr>
    <tr><td>Instalación de bomba de calor</td><td>$14,000</td><td>CleanBC $6,000 + Hogares más ecológicos $5,000</td><td>$3,000</td></tr>
    <tr><td>Aislamiento del ático</td><td>$8,000</td><td>CleanBC $3,000 + Hogares más ecológicos $2,000</td><td>$3,000</td></tr>
