    <tr><td>히트펌프 설치</td><td>$14,000</td><td>CleanBC $6,000 + 친환경 주택 $5,000</td><td>$3,000</td></tr>
    <tr><td>다락방 단열</td><td>$8,000</td><td>CleanBC $3,000 + 친환경 주택 $2,000</td><td>$3,000</td></tr>
    <tr><td><strong>총</strong></td><td><strong>$95,000</strong></td><td><strong>$18,700</strong></td><td><strong>$76,300</strong></td></tr>
