    <tr><td>Air source heat pump (pinapalitan ang gas furnace)</td><td>$3,000 – $6,000</td><td>$5,000</td><td>$11,000</td></tr>
    <tr><td>Heat pump pampainit ng tubig</td><td>$1,000</td><td>$250</td><td>$1,250</td></tr>
    <tr><td>Pag-upgrade ng pagkakabukod (attic, mga dingding)</td><td>Hanggang $6,500</td><td>Hanggang $5,000</td><td>$11,500</td></tr>
