    <tr><td>Máy nước nóng bơm nhiệt</td><td>$1,000</td><td>$250</td><td>$1,250</td></tr>
    <tr><td>Nâng cấp cách nhiệt (gác mái, tường)</td><td>Lên tới $6,500</td><td>Lên tới $5,000</td><td>$11,500</td></tr>
    <tr><td>Bộ sạc EV (Cấp 2)</td><td>$350</td><td>—</td><td>$350</td></tr>
