    <tr><td>Phí pháp lý (cả hai bên)</td><td>$3,000 – $5,000</td></tr>
    <tr><td>Di chuyển vật lý</td><td>$3,000 – $10,000</td></tr>
    <tr><td><strong>Tổng xung đột giao dịch</strong></td><td><strong>$78,000 – $170,000</strong></td></tr>
