UPDATE blog_posts SET localizations = jsonb_set(localizations, ARRAY['contentAr'], to_jsonb('<article>
<p class="lead">تطرح كولومبيا البريطانية شيئين مختلفين تمامًا على الأشخاص الذين يبنون هنا. في جبال ممر البحر إلى السماء، يبدأ المشروع بأرض خام ومنحدرة - صخور من الجرانيت، ودرجات شديدة، وأحمال ثلجية من شأنها أن تسطح تصميم الأراضي المسطحة. وفي قلب مترو فانكوفر الكثيف، يتمثل التحدي في عكس ذلك: تحويل المنازل والمساحات التجارية القائمة بالفعل، والتي لا تزال مشغولة في كثير من الأحيان، ومحاصرة من قبل الجيران وقواعد الستراتا. يجمع هذا الدليل بين اثنين من بناة BC - واحد من كل عالم - لإظهار ما يتطلبه الأمر فعليًا للبناء بشكل جيد على طرفي الطيف.</p>

<h2>طرفي طيف البناء كولومبيا البريطانية</h2>
<p>يبدو البناء والتجديد الجديدان من الخارج مثل نفس التجارة، لكنهما على أرض الواقع متناقضان تقريبًا. يبدأ المرء بموقع فارغ ويضيف كل شيء؛ والآخر يبدأ بمبنى مكتمل ويجب أن يعمل ضمن ما هو موجود بالفعل ويحميه. أقل، <strong>Reno Stars</strong> يغطي تجديد المنازل والمساحات التجارية القائمة في مترو فانكوفر، و <a href="https://keystonepossibilities.ca">إمكانيات كيستون</a> يغطي بناء المنازل المخصصة من الأرض إلى الأعلى في ممر البحر إلى السماء.</p>

<h2>الجزء الأول - تجديد المنازل والمساحات التجارية القائمة في مترو فانكوفر</h2>
<p><em>بقلم هونج مينج وانج، قائد المشروع في Reno Stars</em></p>

<h3>نوع مختلف من البناء: العمل ضمن ما هو موجود بالفعل</h3>
<p>في حين أن المنزل الجبلي المخصص يبدأ من أرض خام، فإن عملنا يبدأ في الطرف الآخر من الطيف - تحويل المنازل والمساحات التجارية القائمة بالفعل، والتي غالبًا ما لا تزال مشغولة، في مناطق حضرية ضيقة عبر برنابي وفانكوفر وريتشموند وبقية مترو فانكوفر. عبر أكثر من 900 مشروع مكتمل، تخصصت Reno Stars في أربعة مجالات حيث تكون خبرة التجديد أكثر أهمية: <strong>المطابخ والحمامات وإعادة تشكيل المنزل بالكامل والتجهيزات التجارية</strong>. التحدي هنا لا يكمن في الحفر أو استقرار المنحدرات، بل في الدقة داخل القيود: الهيكل الحالي، وقواعد الستراتا، والمرافق الحية، والمباني المشغولة، وتصاريح التجديد البلدية.</p>
<p><img src="https://pub-b88db8c50fd64a9a87f60a4486a4a488.r2.dev/uploads/admin/socail-ready-hero-mmwlwyk0.jpg" alt="Custom kitchen renovation with gold fixtures in Burnaby by Reno Stars"></p>

<h3>المطابخ والحمامات - جوهر محفظتنا</h3>
<p>تتمثل غالبية أعمالنا في تجديد المطبخ والحمام بتفاصيل عالية - الغرف حيث تفصل تفاوتات التشطيب والعزل المائي وتنسيق التركيبات بين التجديد الدائم ورد الاتصال. في المنزل الراسخ، يعني ذلك حماية ما يبقى أثناء إعادة بناء ما لم يبقى، كل ذلك بسعر ثابت وشامل التصريح. تشمل الأمثلة الحديثة أ <a href="/en/projects/custom-kitchen-renovation-burnaby/">تجديد المطبخ المخصص مع التركيبات الذهبية</a> و أ <a href="/en/projects/luxury-bathroom-renovation-burnaby/">حمام فاخر مع ميزات مخصصة</a>وكلاهما في برنابي.</p>
<p><img src="https://pub-b88db8c50fd64a9a87f60a4486a4a488.r2.dev/uploads/admin/socail-ready-hero-mmwlwzp2.jpg" alt="Luxury bathroom renovation with custom walk-in shower in Burnaby by Reno Stars"></p>

<h3>المنزل بالكامل والتجاري - التجديد على نطاق واسع</h3>
<p>إلى جانب الغرف الفردية، نقوم بإعادة تصميم المنزل بالكامل والتجهيزات التجارية حيث يكون الجدول الزمني واستمرارية العمل هو كل شيء. في العمل التجاري – مثل أعمالنا <a href="/en/projects/dental-clinic-renovation-burnaby/">عيادة برنابي لطب الأسنان</a> و أ <a href="/en/projects/vancouver-custom-whole-house-renovation/">تجديد مخصص للمنزل بالكامل في فانكوفر</a> - نقوم بتصميم مراحل حول عمليات العميل حتى يستمر العمل. يأتي هذا الانضباط فقط من تجديد المساحات الحية المشغولة بدلاً من البناء على أرض فارغة.</p>
<p><img src="https://pub-b88db8c50fd64a9a87f60a4486a4a488.r2.dev/uploads/admin/vancouver-custom-whole-house-renovation-hero-mmtwqbrf.jpg" alt="Custom whole-house renovation in Vancouver by Reno Stars"></p>

<h3>ما الذي يميز عملية التجديد لدينا؟</h3>
<ul>
<li><strong>عقود ثابتة السعر</strong> مع نطاق مكتوب - لا توجد مفاجآت عند التفتيش.</li>
<li><strong>السماح بالتنسيق</strong> يتم التعامل معها نيابةً عنك، بما في ذلك متطلبات فصل الحرائق والخروج.</li>
<li><strong>تأمين CGL بقيمة 5 ملايين دولار</strong> وكامل <strong>WorkSafeBC</strong> التغطية في كل موقع.</li>
<li>أ <strong>ضمان صنعة لمدة 3 سنوات</strong> دعم العمل النهائي.</li>
</ul>
<p>يستكشف <a href="/en/services/">خدمات التجديد لدينا</a> عبر برنابي ومترو فانكوفر.</p>

<h2>الجزء الثاني - الاستقرار الجيوتقني واستقرار المنحدرات من البحر إلى السماء</h2>
<p><em>بقلم واين ستيفنسون، المشرف ومؤسس <a href="https://keystonepossibilities.ca">إمكانيات كيستون</a></em></p>

<h3>واقع تنمية الجبال الساحلية</h3>
<p>يمثل بناء المنازل المخصصة والمجمعات المتعددة على طول ممر Sea-to-Sky - الذي يمتد ويست فانكوفر وسكواميش وويسلر - إحدى بيئات الهندسة المدنية الأكثر تطلبًا في أمريكا الشمالية. على عكس الطين الجليدي الأكثر ليونة في حوض مترو فانكوفر، تتكون المنحدرات الجبلية لسلسلة الساحل من تربة جليدية شديدة الضغط وتربة كولوفيوم وصخور جرانيتية صلبة. يتطلب تحديد المواقع على هذه الدرجات من 30 إلى 45 درجة التغلب على قطرات الارتفاع الشديدة، وإدارة أحمال الثلوج الديناميكية التي تتراوح من 3.0 كيلو باسكال عند مستوى سطح البحر إلى 10.0+ كيلو باسكال في مناطق ويسلر المرتفعة في جبال الألب، وتوجيه جريان مياه الأمطار الساحلية الغزيرة.</p>
<p><img src="https://pub-b88db8c50fd64a9a87f60a4486a4a488.r2.dev/uploads/admin/keystone-whistler-geotechnical-survey.jpg" alt="Geotechnical ground assessment with a survey tripod on a steep Sea-to-Sky building lot near Whistler"></p>

<h3>تفجير الصخور، والجدران الاستنادية، والإعداد الجيوتقني</h3>
<p>يتطلب تطوير غلاف مبنى مستقر على منحدر من الجرانيت إعدادًا متخصصًا للموقع يختلف بشكل أساسي عن التنقيب الحضري:</p>
<ol>
<li><strong>تقييمات استقرار المنحدر:</strong> بموجب اللوائح البلدية المحلية، فإن أي تطوير على المنحدرات التي تتجاوز 25% يتطلب تصريح تطوير منحدر حاد (DP). يجب على المهندس الجيوتقني المسجل إجراء تقييم شامل للمخاطر، ورسم خرائط للانهيارات الصخرية المحتملة، وتدفقات الحطام، ومخاطر قص التربة الزلزالية.</li>
<li><strong>تثبيت وشد حجر الأساس:</strong> لتأمين الأساسات ضد الجاذبية والأحمال الجانبية الزلزالية، يتم تثبيت الأساسات مباشرة في الجرانيت الصلب - حفر آبار عميقة وتركيب مسامير صخرية فولاذية مشدودة ثقيلة الحجم (عادةً حديد التسليح رقم 25 أو رقم 32) ومليئة بمادة إيبوكسي عالية القوة غير قابلة للانكماش.</li>
<li><strong>تفجير الصخور الخاضعة للرقابة:</strong> تتطلب إزالة آلاف الأمتار المكعبة من الصخور الصلبة تفجير متفجرات خاضعة للرقابة أو كسر المطرقة الهيدروليكية الثقيلة. يجب أن يتم تصميم التفجير باستخدام أنماط تأخير دقيقة ورصد الزلازل لمنع الاهتزازات من إتلاف الأساسات السكنية المجاورة.</li>
</ol>
<p><img src="https://pub-b88db8c50fd64a9a87f60a4486a4a488.r2.dev/uploads/admin/keystone-bedrock-excavation-retaining-wall.jpg" alt="Excavator digging granite bedrock beside an engineered concrete retaining wall in the Sea-to-Sky corridor"></p>

<h3>الهيدرولوجيا البيئية والآثار المرتفعة</h3>
<p>تعد إدارة المياه العامل الوحيد الأكثر أهمية في سلامة المنحدر. يجب توجيه الجريان السطحي عالي السرعة بعيدًا عن الأساس عبر خنادق اعتراضية مخصصة ومستنقعات، وتوجيه مياه الأمطار إلى صهاريج احتجاز مصممة هندسيًا أو أحواض صخرية. في مناطق المراوح الغرينية ومخاطر الفيضانات في سكواميش، يجب على البناة أيضًا الالتزام بمستويات البناء الصارمة للفيضانات (FCL)، وبناء مساحات المعيشة الأساسية فوق مستوى الفيضان لمدة 200 عام باستخدام أرصفة خرسانية مرتفعة، أو أعمدة هيكلية، أو حدائق المنصة.</p>
<p><img src="https://pub-b88db8c50fd64a9a87f60a4486a4a488.r2.dev/uploads/admin/keystone-whistler-custom-home.jpg" alt="Completed modern wood-and-stone custom home on a mountain slope in the Whistler area by Keystone Possibilities"></p>

<h3>إمكانيات كيستون – أوراق اعتماد البحر إلى السماء</h3>
<ul>
<li>مسجل <a href="https://keystonepossibilities.ca">بناء سكني مرخص</a> ومعتمد من ضمان المنزل الوطني.</li>
<li>مقاول مدني مائي مرخص في كولومبيا البريطانية.</li>
<li>التخصص: إدارة الإنشاءات شديدة الانحدار، وحفر الصخور السائبة، وترسيخ الأساس، وتجميع الهياكل الخشبية الثقيلة.</li>
</ul>

<h2>الخيط المشترك</h2>
<p>سواء كنت تقوم بتثبيت أساس منحدر صخري في جرانيت ويسلر أو إعادة بناء مطبخ مستقل مشغول في برنابي، فإن الأساسيات متطابقة: الخبرة الإقليمية المناسبة، والنطاق الثابت المتفق عليه مقدمًا، والباني الذي يخطط للتغلب على قيود العالم الحقيقي للموقع. البناء الجديد والتجديد هما حرفتان مختلفتان - ولكن في جميع أنحاء كولومبيا البريطانية، كلاهما يعيش أو يموت في نفس التخصص.</p>
</article>'::text)) WHERE id = '0b513be9-6630-4ca1-bdcc-a2cbf0dfb26d' AND localizations->>'contentAr' = '<article>
<p class="lead">تطرح كولومبيا البريطانية شيئين مختلفين تمامًا على الأشخاص الذين يبنون هنا. في جبال ممر البحر إلى السماء، يبدأ المشروع بأرض خام ومنحدرة - صخور من الجرانيت، ودرجات شديدة، وأحمال ثلجية من شأنها أن تسطح تصميم الأراضي المسطحة. وفي قلب مترو فانكوفر الكثيف، يتمثل التحدي في عكس ذلك: تحويل المنازل والمساحات التجارية القائمة بالفعل، والتي لا تزال مشغولة في كثير من الأحيان، ومحاصرة من قبل الجيران وقواعد الستراتا. يجمع هذا الدليل بين اثنين من بناة BC - واحد من كل عالم - لإظهار ما يتطلبه الأمر فعليًا للبناء بشكل جيد على طرفي الطيف.</p>

<h2>طرفي طيف البناء كولومبيا البريطانية</h2>
<p>يبدو البناء والتجديد الجديدان من الخارج مثل نفس التجارة، لكنهما على أرض الواقع متناقضان تقريبًا. يبدأ المرء بموقع فارغ ويضيف كل شيء؛ والآخر يبدأ بمبنى مكتمل ويجب أن يعمل ضمن ما هو موجود بالفعل ويحميه. أقل، <strong>Reno Stars</strong> يغطي تجديد المنازل والمساحات التجارية القائمة في مترو فانكوفر، و <a href="https://keystonepossibilities.ca">إمكانيات كيستون</a> يغطي بناء المنازل المخصصة من الأرض إلى الأعلى في ممر البحر إلى السماء.</p>

<h2>الجزء الأول - تجديد المنازل والمساحات التجارية القائمة في مترو فانكوفر</h2>
<p><em>بقلم هونج مينج وانج، قائد المشروع في Reno Stars</em></p>

