UPDATE blog_posts SET localizations = jsonb_set(localizations, ARRAY['contentVi'], to_jsonb('<p>Nếu bạn&#39;đang lên kế hoạch cải tạo ở Burnaby, con số hữu ích nhất không phải là&#39;trung bình trong ngành - đó là số tiền mà hàng xóm của bạn thực sự đã trả. Hướng dẫn này chia nhỏ mức giá thực tế từ 8 dự án Reno Stars đã hoàn thành trên khắp các nhà phố, nhà ở dành cho một gia đình và không gian thương mại ở Burnaby, tất cả đều được hoàn thành trong vòng 18 tháng qua.</p>
